/// RecLite native recording engine.
///
/// The app talks to the engine only through [RecliteEngine]. The underlying
/// messages are generated by Pigeon from `pigeons/engine_api.dart`.
library;

import 'src/messages.g.dart';

export 'src/messages.g.dart' show DiskSpace, EngineCapabilities, HostPlatform;

class RecliteEngine {
  RecliteEngine({EngineHostApi? hostApi}) : _api = hostApi ?? EngineHostApi();

  final EngineHostApi _api;

  /// What this machine/OS supports. Call once at startup.
  Future<EngineCapabilities> getCapabilities() => _api.getCapabilities();

  /// Free/total space of the volume holding [path].
  ///
  /// Throws a `PlatformException` with code `invalid_path` if [path] does not
  /// exist.
  Future<DiskSpace> getDiskSpace(String path) => _api.getDiskSpace(path);
}
